<script setup lang="ts">
import {ref,onMounted} from 'vue'
type Customer={id:string;name:string;country:string;person:string;email:string;product:string;stage:string}
const rows=ref<Customer[]>([]),total=ref(0),page=ref(1),q=ref(''),stage=ref(''),busy=ref(false),error=ref(''),success=ref(''),editing=ref(false),current=ref<Customer>(),contacts=ref<{id:string;name:string;email:string;role:string}[]>([]),logs=ref<{id:string;content:string;created_at:string}[]>([])
const sources=ref<{url:string;platform:string;evidence:string;review_note:string}[]>([])
const stages=['待联系','初步接洽','重点跟进','已发报价','已成交']
const empty=()=>({id:'',name:'',country:'',person:'',email:'',product:'',stage:'待联系'})
const form=ref(empty()),contact=ref({name:'',email:'',role:''}),note=ref('')
async function api(path:string,method='GET',body?:unknown){const r=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw new Error(d.error||'请求失败');return d}
async function action(fn:()=>Promise<void>){busy.value=true;error.value='';success.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'连接失败'}finally{busy.value=false}}
async function list(){const d=await api('customers?'+new URLSearchParams({q:q.value,stage:stage.value,page:String(page.value)}));rows.value=d.items;total.value=d.total}
function load(reset=false){if(reset)page.value=1;action(list)}
function edit(c?:Customer){form.value=c?{...c}:empty();editing.value=true}
function save(){action(async()=>{await api('customers'+(form.value.id?'/'+form.value.id:''),form.value.id?'PUT':'POST',form.value);editing.value=false;await list();if(current.value?.id===form.value.id)current.value={...form.value};success.value='客户已保存到 MySQL'})}
async function details(c:Customer){current.value=c;contacts.value=[];logs.value=[];contact.value={name:'',email:'',role:''};note.value='';await action(async()=>{const [a,b,d]=await Promise.all([api(`customers/${c.id}/contacts`),api(`customers/${c.id}/followups`),api(`customers/${c.id}/sources`)]);contacts.value=a;logs.value=b;sources.value=d})}
function addContact(){action(async()=>{await api(`customers/${current.value!.id}/contacts`,'POST',contact.value);contacts.value=await api(`customers/${current.value!.id}/contacts`);contact.value={name:'',email:'',role:''};success.value='联系人已保存'})}
function addNote(){action(async()=>{await api(`customers/${current.value!.id}/followups`,'POST',{content:note.value});logs.value=await api(`customers/${current.value!.id}/followups`);note.value='';success.value='跟进记录已保存'})}
onMounted(()=>load())
</script>
<template><section class="panel"><div class="section-title"><div><h2>真实客户资产库</h2><p>服务器 MySQL · 与演示客户独立保存 · 本地开发模式</p></div><button class="primary" :disabled="busy" @click="edit()">＋ 新增真实客户</button></div><p v-if="error" role="alert" class="error">{{error}} <button :disabled="busy" @click="load()">重试</button></p><p v-if="success" role="status" class="notice">{{success}}</p><form class="filters" @submit.prevent="load(true)"><input v-model="q" placeholder="公司 / 联系人 / 国家" aria-label="搜索真实客户"/><select v-model="stage" aria-label="筛选客户阶段"><option value="">全部阶段</option><option v-for="s in stages">{{s}}</option></select><button :disabled="busy">查询</button></form><p v-if="busy" role="status">正在处理…</p><div class="table-wrap"><table><thead><tr><th>公司 / 联系人</th><th>国家</th><th>产品</th><th>阶段</th><th>操作</th></tr></thead><tbody><tr v-for="c in rows" :key="c.id"><td><b>{{c.name}}</b><small>{{c.person||'未填写联系人'}}</small></td><td>{{c.country||'—'}}</td><td>{{c.product||'—'}}</td><td>{{c.stage}}</td><td><button :disabled="busy" @click="edit(c)">编辑</button> <button :disabled="busy" @click="details(c)">联系人与跟进</button></td></tr></tbody></table></div><p v-if="!rows.length&&!busy&&!error" class="empty">暂无真实客户，点击新增开始；系统不会自动导入演示数据。</p><div class="pagination"><span>共 {{total}} 位 · 第 {{page}} 页</span><button :disabled="busy||page===1" @click="page--;load()">上一页</button><button :disabled="busy||page*20>=total" @click="page++;load()">下一页</button></div></section>
<div v-if="editing" class="overlay" @click.self="!busy&&(editing=false)"><form class="dialog" @submit.prevent="save"><h2>{{form.id?'编辑客户':'新增真实客户'}}</h2><label v-for="(label,key) in {name:'公司名称',country:'国家 / 地区',person:'主要联系人',email:'邮箱',product:'关注产品'}">{{label}}<input v-model="form[key]" :required="key==='name'" :maxlength="key==='email'?254:key==='country'||key==='person'?100:200" :type="key==='email'?'email':'text'"/></label><label>客户阶段<select v-model="form.stage"><option v-for="s in stages">{{s}}</option></select></label><p v-if="error" role="alert" class="error">{{error}}</p><button class="primary" :disabled="busy">保存到数据库</button> <button type="button" :disabled="busy" @click="editing=false">取消</button></form></div>
<section v-if="current" class="panel spaced"><div class="section-title"><h2>{{current.name}} · 客户详情</h2><button @click="current=undefined">收起</button></div><div v-if="sources.length" class="spaced"><h2>获客来源与审核证据</h2><article v-for="s in sources" class="log"><a :href="s.url" target="_blank" rel="noopener noreferrer">{{s.platform}} · 原始主页 ↗</a><p class="note-content">{{s.evidence}}</p><small>{{s.review_note}}</small></article></div><div class="follow-grid"><div><h2 class="spaced">联系人</h2><p v-for="c in contacts" :key="c.id">{{c.name}} · {{c.role||'职位待补充'}} · {{c.email}}</p><form @submit.prevent="addContact"><label>姓名<input v-model="contact.name" required maxlength="100"/></label><label>岗位<input v-model="contact.role" maxlength="100"/></label><label>邮箱<input v-model="contact.email" type="email" maxlength="254"/></label><button :disabled="busy">添加联系人</button></form></div><div><h2 class="spaced">沟通时间线</h2><form @submit.prevent="addNote"><textarea v-model="note" required maxlength="10000" rows="4" placeholder="客户需求、沟通结果、下一步安排…" aria-label="跟进内容"></textarea><button class="primary" :disabled="busy||!note.trim()">保存跟进</button></form><article class="log" v-for="l in logs" :key="l.id"><small>{{new Date(l.created_at).toLocaleString('zh-CN')}}</small><p class="note-content">{{l.content}}</p></article><p v-if="!logs.length">暂无跟进记录</p></div></div></section></template>
<style scoped>.error{background:#fbe8ed;color:#983e55;padding:12px;border-radius:5px}.pagination{display:flex;gap:12px;align-items:center;justify-content:flex-end;margin-top:20px;font-size:12px}.note-content{white-space:pre-wrap;overflow-wrap:anywhere}.overlay{z-index:20}button:disabled{cursor:wait}td button{font-size:11px}</style>
